files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f9f9f9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #247cff;
  --vt-on-accent: #000000;
  --vt-accent-ink: #247cff;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;
}

.root {
  font-family: 'Open Sans', sans-serif;
  line-height: 1.5;
  color: var(--vt-ink-soft);
  background: var(--vt-surface);
  min-height: 100vh;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Navbar */
.root .nav {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 20px 0;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1030;
}

.root .navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.root .logo {
  color: var(--vt-accent);
  font-size: 24px;
  font-weight: 700;
  text-align: center;
  text-decoration: none;
}

.root .brand {
  display: block;
  font-size: 24px;
  font-weight: 700;
  color: var(--vt-accent);
  line-height: 1.2;
}

.root .brand strong {
  color: var(--vt-ink-soft);
  font-size: 12px;
  font-weight: 400;
  display: block;
}

.root .navLinks {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

.root .navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  padding: 15px 0;
}

.root .navLinks a:hover,
.root .navLinks a:focus {
  color: var(--vt-ink);
}

/* Hero */
.root .hero {
  padding-top: 0;
}

.root .heroContainer {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.root .heroSlider {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
}

.root .heroSlider::-webkit-scrollbar {
  display: none;
}

.root .heroSlide {
  min-width: 100%;
  scroll-snap-align: start;
  position: relative;
}

.root .heroImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.root .heroText {
  background: var(--vt-surface);
  position: absolute;
  z-index: 2;
  bottom: 0;
  right: 0;
  padding: 1.5rem 2.5rem;
  width: 50%;
}

.root .heroTitle {
  color: var(--vt-ink);
  font-size: 48px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 0.5rem;
}

.root .heroDesc {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin-bottom: 1.5rem;
}

.root .heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.root .customLink {
  display: inline-block;
  text-decoration: none;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  box-sizing: border-box;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
  transition: all 0.3s;
  background: transparent;
}

.root .customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--vt-line);
  color: var(--vt-accent);
  text-align: center;
  transition: top 300ms cubic-bezier(0.19, 1, 0.56, 1);
  display: flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  padding: 0 30px;
}

.root .customLink:hover::before {
  top: 0;
}

.root .contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin: 0 0 0 2rem;
}

/* Sections general */
.root .sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.root .container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

/* About section */
.root .aboutRow {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 3rem;
}

.root .aboutColText {
  flex: 1 1 50%;
}

.root .aboutColImage {
  flex: 0 0 40%;
  max-width: 400px;
  margin: 0 auto;
}

.root .aboutImage {
  width: 100%;
  height: auto;
  border-radius: 50%;
  object-fit: cover;
}

.root .aboutTitle {
  color: var(--vt-ink);
  font-size: 36px;
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 1rem;
}

.root .aboutText {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.6;
}

/* Gallery */
.root .gallery {
  padding: 0;
}

.root .galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.root .galleryCol {
  flex: 1 1 50%;
  max-width: 50%;
}

.root .galleryImage {
  width: 100%;
  height: auto;
  display: block;
}

/* Timeline */
.root .timelineSection {
  padding-bottom: 0;
}

.root .timelineTitle {
  color: var(--vt-ink);
  font-size: 36px;
  font-weight: 700;
  text-align: center;
  margin-bottom: 3rem;
}

.root .timeline {
  position: relative;
}

.root .timeline::before {
  content: "";
  display: block;
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.root .timelineNode {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 4rem;
}

.root .timelineNode:nth-child(odd) {
  flex-direction: row;
}

.root .timelineNode:nth-child(even) {
  flex-direction: row-reverse;
}

.root .timelineDate {
  flex: 0 0 35%;
  max-width: 35%;
  padding: 1rem 0;
}

.root .timelineNode:nth-child(odd) .timelineDate {
  text-align: right;
  order: 1;
}

.root .timelineNode:nth-child(even) .timelineDate {
  text-align: left;
  order: 3;
}

.root .timelineIconWrap {
  flex: 0 0 80px;
  width: 80px;
  height: 80px;
  position: relative;
  z-index: 100;
  order: 2;
  margin: 0 1rem;
}

.root .timelineIcon {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
}

.root .timelineContent {
  flex: 0 0 35%;
  max-width: 35%;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  position: relative;
  order: 1;
}

.root .timelineNode:nth-child(odd) .timelineContent {
  order: 3;
}

.root .timelineNode:nth-child(even) .timelineContent {
  order: 1;
}

.root .timelineHeading {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
  font-size: 32px;
  font-weight: 600;
}

.root .timelineNode:nth-child(odd) .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.root .timelineNode:nth-child(even) .timelineHeading::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translate(0, -50%);
  width: 0;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.root .timelineText {
  padding: 10px 30px;
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin: 0;
}

/* Contact section */
.root .contactSection {
  background: var(--vt-surface-2);
}

.root .contactTitle {
  color: var(--vt-ink);
  font-size: 36px;
  font-weight: 700;
  text-align: center;
  margin-bottom: 3rem;
}

.root .contactWrap {
  max-width: 800px;
  margin: 0 auto;
}

.root .socialLinks {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

/* Footer */
.root .footer {
  background: var(--vt-surface-2);
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.root .footerRow {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

.root .footerCol {
  flex: 1 1 calc(33.333% - 2rem);
  min-width: 250px;
}

.root .footerHeading {
  color: var(--vt-ink);
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 1.5rem;
}

.root .hoursText,
.root .footerText {
  color: var(--vt-ink-soft);
  font-size: 16px;
  line-height: 1.6;
  margin: 0;
}

.root .footerSocial {
  display: flex;
  gap: 1rem;
}

.root .footerColCopyright {
  flex-basis: 100%;
  text-align: center;
  margin-top: 2rem;
}

.root .copyrightText {
  color: var(--vt-ink-soft);
  font-size: 16px;
}

/* Responsive adjustments */
@media screen and (min-width: 1600px) {
  .root .heroContainer {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root .heroTitle {
    font-size: 38px;
  }

  .root .aboutTitle,
  .root .timelineTitle,
  .root .contactTitle {
    font-size: 32px;
  }

  .root .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .root .heroContainer {
    height: auto;
  }

  .root .heroText {
    position: relative;
    bottom: auto;
    left: auto;
    width: auto;
    margin-bottom: 0;
    padding: 2rem;
    background: var(--vt-surface);
  }

  .root .aboutRow {
    flex-direction: column;
    text-align: center;
  }

  .root .aboutColImage {
    flex: 0 0 auto;
    max-width: 300px;
  }

  .root .galleryCol {
    flex: 1 1 50%;
    max-width: 50%;
  }
}

@media screen and (max-width: 767px) {
  .root .navIn {
    flex-direction: column;
    align-items: flex-start;
  }

  .root .navLinks {
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 1rem;
  }

  .root .heroText {
    padding: 1.5rem;
  }

  .root .timeline::before {
    top: 60px;
    left: 33px;
    height: 90%;
    transform: translateX(-50%);
  }

  .root .timelineNode {
    flex-direction: row !important;
    align-items: flex-start;
  }

  .root .timelineDate {
    flex: 0 0 auto;
    max-width: none;
    text-align: left !important;
    order: 1;
    padding-left: 60px;
  }

  .root .timelineIconWrap {
    position: absolute;
    left: 0;
    top: 60px;
    order: 2;
    margin: 0;
  }

  .root .timelineContent {
    flex: 1 1 auto;
    max-width: none;
    order: 3;
    margin-top: 2rem;
  }

  .root .timelineNode:nth-child(odd) .timelineHeading::after,
  .root .timelineNode:nth-child(even) .timelineHeading::after {
    right: 100%;
    left: auto;
    border-left: 0;
    border-right: 10px solid var(--vt-surface-deep);
  }

  .root .footerRow {
    flex-direction: column;
  }
}

@media screen and (max-width: 575px) {
  .root .timeline::before {
    left: 57px;
  }

  .root .timelineIconWrap {
    width: 70px;
    height: 70px;
    left: -10px;
  }

  .root .timelineIcon {
    width: 70px;
    height: 70px;
  }

  .root .timelineDate {
    padding-left: 50px;
  }
}

@media screen and (max-width: 480px) {
  .root .heroText {
    padding: 1rem;
  }

  .root .heroLinks .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
    margin-right: 12px;
  }

  .root .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .root .aboutColImage {
    max-width: 235px;
  }

  .root .timeline::before {
    left: 42px;
  }
}
